/* ======================================================================================
   SCENES: "The 20-20-60 Split" (SRT-timed). Every on-screen word traces to a cue in
   20-20-60.srt (see FLOW.md). Every scene boundary and every reveal is placed on the SRT clock:
   C[n-1] is the start of cue n. Transitions finish exactly on the cue that starts the scene.
   ====================================================================================== */
let SCENES = [], CUES = [], SFX_CUES = [], STORYBOARD = [];

/* SRT:BEGIN (generated by tools/srt_sync.py; do not edit by hand) */
const C = [0.0, 2.4, 4.9, 10.5, 13.8, 16.8, 21.5, 26.4, 29.6, 35.0, 39.8, 44.8, 48.0, 52.5, 58.0, 63.2, 68.5, 73.4, 78.4, 81.5, 85.8, 90.6, 96.2, 99.5, 103.686];
const SRT_TEXT = ["Idha konjam diagrammatic-ah explain panren.", "Idha 20-20-60 split-nu solluvaanga.", "Ippo oru category of people, adhaavadhu first 20 percentage of the people, Never Buy category-kulla varuvaanga.", "Ivanga yen inga irukkaanga-nu avangalukkum theriyaadhu, namakkum theriyaadhu.", "Ivangalukku need irukkaadhu, ivangalaala pay panna mudiyaadhu,", "and at the same time, ivangalukku namma idha evlo kashtappattu sell pannaalum, ivanga kandippaa vaanga maattaanga.", "So, ivangalukku namma efforts poduradhu-ndradhe waste of time. So, ivangalukku sales thevaiye kidaiyaadhu.", "And innoru 20 percentage of people, Definitely Buy.", "Ivanga eppadi-naa Amazon purchasers maadhiri. Ippo namma vandhu oru Amazon-la oru porul vaangurom appadinaa,", "ippo vaangurom—cart-la podrathu kidaiyaadhu—vaangurom appadinaa, oru porul venum-nu decide pannuvom, poi product-ah paappom,", "search pannuvom, description paappom, details nallaa irukkaa-nu paappom, features-laam nallaa irukkaa-nu paappom,", "paatthuttu nallaa irukkaa, purchase pannittu vandhutte iruppom.", "Adhe maadhiri dhaan ivangalum. Nammala patthi, namma website, namma enna sell panrom-ngradha patthi,", "and namma dhaan venum appadindra maadhiri ellaathaiyum paatthuttu, decide pannittu, nammakitta lead-ah vandhiruppaanga.", "So, ivangakitta product-oda features-ah kashtappattu sell pannanum appadindra maadhiri-laam oru avasiyamum kidaiyaadhu.", "Enna irukku, evlo-nu sonnaa podhum, kandippaa vaangirvaanga. Ivanga Definitely Buy category-kulla varuvaanga.", "Aanaa, innoru 60 percentage of people irukkaanga. Ivanga dhaan Confused Buyers.", "So, ivangalukku first indha product mela need irukkaa illaiyaa, yaarukitta vaanguradhu,", "and vaanginaa use pannuvaangalaa maattaangalaa,", "and ippo adhu avangalukku thevaiyaa illa future-la thevaiyaa, illa idhukku badhilaa avangalukku vera edhaavadhu thevaiyaa,", "indha maadhiri multiple confusions irukkum, and ivangalukku decision making-la oru help thevaippadum.", "And yaaraavadhu help pannaa mattum dhaan ivangalukku edhu thevai, thevai illai-ne decide panna mudiyum-ndra oru situation-la iruppaanga.", "Ivangalukkaaga dhaan sales appadindra oru vishayame exist aagudhu.", "Adhaavadhu, confusion-la irukkavangalukku clarity kodutthu, decision making-la help panradhukku."];
/* SRT:END */
const GY = 860;                         // ground line
const TR = 0.7, TRW = 1.0;              // TRW: the diagonal wipes run a little longer so they stay smooth                         // transition length; the incoming scene starts TR before its cue
// Spine object: one bar, 10 slots (1 figure = 10%), split 20 | 20 | 60
const BAR = { x: 260, w: 1400, h: 64 };
const SHARES = [0.2, 0.2, 0.6];          // spine bar shares (must sum to 1)
const SLOT = i => BAR.x + 70 + 140 * i;
const GROUP = ['NEVER BUY', 'DEFINITELY BUY', 'CONFUSED BUYERS'];
const WEAR = ['bucket', 'capBack', 'specs', 'specs', 'beanie', 'bun', 'cap', 'none', 'bun', 'beanie']; // crowd slot -> look

function buildScenes() {
  const W = CONFIG.width, H = CONFIG.height;
  const KNOT = knotPts(0, 0, 110);
  THREAD = []; THC = [930, 430];
  { const M = 260, lead = 26, a0 = Math.PI;
    const loop = u => { const a = a0 + u * Math.PI * 7, r = 64 + 20 * Math.sin(u * Math.PI * 4.6 + .6);
      return [THC[0] + Math.cos(a) * r * 1.3 + (u - .5) * 90, THC[1] + Math.sin(a) * r * .78]; };
    const s0 = loop(0); for (let i = 0; i < lead; i++) { const u = i / lead; THREAD.push([lerp(600, s0[0], u), lerp(LYS, s0[1], u)]); }
    for (let i = 0; i < M; i++) THREAD.push(loop(i / (M - 1))); }

  SCENES = [
    /* 1. THE 20-20-60 SPLIT  (cues 1-3)  each group walks in acting its nature -> the bar splits -> first 20% = NEVER BUY */
    { id: 'split', start: 0, end: cue(4) - .001,
      camera: t => tween([[0, { x: 0, y: 30, z: 1.06 }], [2.2, { x: 0, y: 0, z: 1 }], [wordAt(3, '20 percentage'), { x: -70, y: 20, z: 1.05 }], [wordAt(3, 'Never Buy') + .4, { x: -540, y: 80, z: 1.3 }]], t),
      draw(g, t, T, c) {
        NOW = t; dotGrid(g, c);
        const W20 = wordAt(3, '20 percentage'), WNB = wordAt(3, 'Never Buy'), red0 = prog(t, WNB, WNB + .5);
        world(g, c, () => {
          groundLine(g, GY, prog(t, 0, .8));
          const col = [red0 > .5 ? PAL.red : PAL.ink, rgba(PAL.ink, 1 - .55 * red0), rgba(PAL.ink, 1 - .55 * red0)];
          const nA = prog(t, cue(2) + 1.0, cue(2) + 1.6), nOut = 1 - prog(t, W20 + .1, W20 + .5);
          spineBar(g, prog(t, cue(2), cue(2) + 1.2), col, [nA, nA * nOut, nA * nOut], [prog(t, WNB, WNB + .6), 0, 0], { crack: prog(t, cue(2) + .7, cue(2) + 1.3) });
          for (let i = 0; i < 10; i++) {
            const x = SLOT(i), grp = i < 2 ? 0 : i < 4 ? 1 : 2;
            // nobody's kind is shown before it is spoken: all ten walk in alike; the Never Buy pair is revealed on "Never Buy"
            const kf = [[.15 + i * .08, x - 1300], [1.9 + i * .05, x, E.out]];
            let rest = POSES.stand;
            if (grp === 0) rest = poseMix(POSES.stand, POSES.cross, E.inOut(prog(t, WNB + .2, WNB + .8)));
            const w = walker(kf, t, .75, rest, 1);
            const colr = grp === 0 ? (red0 > .5 ? PAL.red : PAL.ink) : rgba(PAL.ink, 1 - .55 * red0);
            const F = { x: w.x, y: GY, s: .75, pose: idle(w.pose, t, i), facing: w.facing, color: colr, seed: i, expr: 'neutral',
              wear: grp === 0 && t > WNB + .2 ? WEAR[i] : null };
            person(g, F);
          }
        });
        subline(g, 'Let me explain it with a diagram', 960, 210, prog(t, .3, .9), prog(t, cue(2) - .3, cue(2)), { align: 'center', size: 44, color: PAL.gray, face: 'label' });
        fadeAlpha(g, 1 - prog(t, W20 - .4, W20), () => headline(g, 'THE 20-20-60 SPLIT', 960, 230, prog(t, cue(2), cue(2) + 1.1), { align: 'center', size: 96, red: [1] }));
        headlineWords(g, t, ['20%', 'NEVER', 'BUY'], [W20, WNB, WNB + .12], 140, 230, { size: 92, red: [1, 2] });
      } },

    /* 2. NEVER BUY  (cues 4-7)  nobody knows why they're here; no need, empty wallet; pitches bounce off; sales not needed */
    { id: 'never', start: cue(4) - TR, end: cue(8) - .001, enter: { type: 'iris', x: 400, y: 640, dur: TR },
      camera: t => { const a = t + cue(4) - TR; return tween([[cue(4) - TR, { x: 0, y: 0, z: 1.08 }], [cue(4) + 1.5, { x: 0, y: 0, z: 1 }], [cue(6) + 1.0, { x: 0, y: 0, z: 1 }],
        [cue(6) + 2.6, { x: -60, y: 70, z: 1.12 }], [cue(7) + .2, { x: -60, y: 70, z: 1.12 }], [cue(7) + 1.4, { x: 0, y: 0, z: 1 }]], a); },
      draw(g, t0, T, c) {
        const t = t0 + cue(4) - TR; NOW = t; dotGrid(g, c);
        const hx = 760, S = 1.15, usKf = [[cue(6), 1420], [cue(6) + 1.4, 1160, E.out], [cue(7) + 1.4, 1160], [cue(7) + 4.4, 1420, E.inOut]];
        const within = (a, b) => t >= a && t < b;
        world(g, c, () => {
          groundLine(g, GY, 1);
          // hero: a Never Buy buyer (red, bucket hat)
          let hp = POSES.stand;
          hp = poseMix(hp, POSES.shrug, E.inOut(prog(t, cue(4) + 1.3, cue(4) + 1.8)));     // looks around, then shrugs
          hp = poseMix(hp, POSES.stop, E.inOut(prog(t, cue(5), cue(5) + .5)));            // "no need"
          hp = poseMix(hp, POSES.reach, E.inOut(prog(t, cue(5) + 1.2, cue(5) + 1.6)));     // "can't pay": shows an empty wallet
          hp = poseMix(hp, POSES.stop, E.inOut(prog(t, cue(6) + 1.0, cue(6) + 1.4)));      // palm up to the pitch
          hp = poseMix(hp, POSES.cross, E.inOut(prog(t, cue(6) + 3.7, cue(6) + 4.2)));     // turns away, arms crossed
          const hexpr = t < cue(5) ? 'confused' : (t > cue(6) + 1.0 ? 'angry' : (t > cue(5) + 1.6 ? 'sad' : 'neutral'));
          const hface = within(cue(4) + .3, cue(4) + 1.1) || t > cue(6) + 3.8 ? -1 : 1;
          const hr = neverBuyer(g, { x: hx, y: GY, s: S, pose: idle(hp, t, 1), facing: hface, color: PAL.red, expr: hexpr, seed: 1, wear: 'bucket' });
          emptyWallet(g, hr.handF[0], hr.handF[1], 1, prog(t, cue(5) + 1.3, cue(5) + 1.8) * (1 - prog(t, cue(6) + .6, cue(6) + .9)), E.inOut(prog(t, cue(5) + 1.9, cue(5) + 2.5)));
          // SALES: red tie + briefcase; looks around too on cue 4
          const uw = walker(usKf, t, S, POSES.reach, -1);
          let up = t < cue(6) ? poseMix(POSES.stand, POSES.shrug, E.inOut(prog(t, cue(4) + 1.5, cue(4) + 2.0))) : uw.pose;
          up = poseMix(up, POSES.slump, E.inOut(prog(t, cue(7) + .1, cue(7) + .7)));
          if (t > cue(7) + 1.4) up = poseMix(uw.pose, POSES.slump, .8);
          const ux = t < cue(6) ? 1420 : uw.x, uface = within(cue(4) + .7, cue(4) + 1.5) || within(cue(7) + 1.4, cue(7) + 4.4) ? 1 : -1;
          const ur = salesman(g, { x: ux, y: GY, s: S, pose: idle(up, t, 2), facing: uface, seed: 2, expr: t > cue(7) ? 'sad' : (t < cue(5) ? 'confused' : 'happy') });
          tag(g, 'SALES', ux, GY + 70, prog(t, cue(4) + .4, cue(4) + .8), { size: 30 });
          briefcase(g, 1520, GY, 1, 1);
          tag(g, 'NEVER BUY', hx, GY + 70, prog(t, cue(4) + .2, cue(4) + .6), { size: 30, bg: PAL.red });
          // cue 4: "?" for both of them, after they look around
          const qOut = 1 - prog(t, cue(5) - .3, cue(5));
          [[hr, 1, cue(4) + 1.4], [ur, -1, cue(4) + 1.7]].forEach(([r, d, a]) => thoughtBubble(g, r.head[0] + 40 * d, r.head[1] - 40, r.head[0] + 150 * d, r.head[1] - 150, 64, prog(t, a, a + 1.0) * qOut, (g2, rr, q) => {
            g2.globalAlpha *= q; g2.font = font('head', 84); g2.fillStyle = PAL.red; g2.textAlign = 'center'; g2.textBaseline = 'middle'; g2.fillText('?', 0, 6); }));
          // cue 6: product pitches fly from the salesman's hand, bounce off the raised palm and drop, going gray
          for (let k = 0; k < 3; k++) {
            const a = cue(6) + 1.4 + k * 1.0, fly = prog(t, a, a + .5), fall = prog(t, a + .5, a + 1.3);
            if (fly <= 0 || fall >= 1) continue;
            const sx = ur.handF[0] - 30, sy = ur.handF[1] - 20, hitX = hx + 110, hitY = 500 + k * 25;
            let x, y, col = PAL.ink;
            if (fall <= 0) { x = lerp(sx, hitX, E.out(fly)); y = lerp(sy, hitY, E.out(fly)) - Math.sin(Math.PI * fly) * 40; }
            else { x = hitX + 90 * fall; y = hitY + (GY - 40 - hitY) * fall * fall - Math.sin(Math.PI * fall) * 60; col = PAL.gray; }
            pitchBubble(g, x, y, 1.4, col, 1 - prog(fall, .75, 1));
          }
          stampX(g, (hx + 1160) / 2, 590, 90, prog(t, cue(7) + .5, cue(7) + .9));
        });
        const hA = (a, b) => { const q = prog(t, a - .1, b); return 1 - q * q; };   // exits: gentle ease-in over 0.4 s
        fadeAlpha(g, hA(cue(5) - .3, cue(5)), () => {
          headline(g, 'WHY ARE THEY HERE?', 140, 230, prog(t, cue(4) + .1, cue(4) + 1.0), { size: 84, red: [3] });
          subline(g, "Not them. Not us.", 140, 302, prog(t, cue(4) + 1.6, cue(4) + 2.1), 0, { size: 40 });
        });
        fadeAlpha(g, hA(cue(6) - .3, cue(6)), () => headline(g, "NO NEED. CAN'T PAY.", 140, 230, prog(t, cue(5) + .1, cue(5) + 1.0), { size: 84, red: [3] }));
        fadeAlpha(g, hA(cue(7) - .3, cue(7)), () => {
          headline(g, "THEY WON'T BUY", 140, 230, prog(t, cue(6) + .1, cue(6) + 1.0), { size: 84, red: [2] });
          subline(g, 'However hard we sell', 140, 302, prog(t, cue(6) + 1.2, cue(6) + 1.7), 0, { size: 40 });
        });
        headline(g, 'SALES? NOT NEEDED.', 140, 230, prog(t, cue(7) + .1, cue(7) + 1.0), { size: 84, red: [0] });
        subline(g, 'Our effort here = waste of time', 140, 302, prog(t, cue(7) + 1.4, cue(7) + 1.9), 0, { size: 40 });
      } },

    /* 3. DEFINITELY BUY  (cues 8-12)  like an Amazon buyer: buy (not just cart), decide, look, search ... features -> purchase */
    { id: 'definite', start: cue(8) - TRW, end: cue(13) - .001, enter: { type: 'wipe', dur: TRW },
      camera: t => tween([[0, { x: 0, y: 0, z: 1.06 }], [2.2, { x: 0, y: 0, z: 1 }], [cue(11) - cue(8) + TRW, { x: 0, y: 0, z: 1 }], [cue(11) - cue(8) + TRW + 1.6, { x: 90, y: 30, z: 1.06 }],
        [cue(12) - cue(8) + TRW + .2, { x: 90, y: 30, z: 1.06 }], [cue(12) - cue(8) + TRW + 1.4, { x: 0, y: 0, z: 1 }]], t),
      draw(g, t0, T, c) {
        const t = t0 + cue(8) - TRW; NOW = t; dotGrid(g, c);
        const SX = 960, SY = 300, SW = 760, SH = 520;
        const rows = [['WANT IT', cue(10) + 1.6], ['SEE PRODUCT', cue(10) + 3.0], ['SEARCH', cue(11) + .1], ['DESCRIPTION', cue(11) + 1.1], ['DETAILS', cue(11) + 2.4], ['FEATURES', cue(11) + 3.6]];
        world(g, c, () => {
          groundLine(g, GY, 1);
          const w = walker([[cue(8) + .1, -200], [cue(8) + 2.0, 520, E.out], [cue(9) + 1.4, 520], [cue(9) + 3.2, 580, E.inOut]], t, 1.15, POSES.stand, 1);
          let pose = w.pose;
          pose = poseMix(pose, POSES.think, E.inOut(prog(t, cue(9) + .8, cue(9) + 1.3)));
          pose = poseMix(pose, POSES.point, E.inOut(prog(t, cue(10) + 1.4, cue(10) + 1.9)));
          pose = poseMix(pose, POSES.reach, E.inOut(prog(t, cue(12) + .1, cue(12) + .5)));
          pose = poseMix(pose, POSES.slump, .35 * Math.sin(Math.PI * prog(t, cue(12) + 1.12, cue(12) + 1.32)));   // anticipation dip
          pose = poseMix(pose, POSES.cheer, E.inOut(prog(t, cue(12) + 1.3, cue(12) + 1.7)) * (1 - E.inOut(prog(t, cue(12) + 2.2, cue(12) + 2.6))));
          // a small nod as each step is ticked
          const nod = rows.reduce((s, [, a]) => s + Math.sin(Math.PI * prog(t, a + .2, a + .6)) * 12, 0);
          pose = Object.assign({}, pose, { head: (pose.head || 0) + nod });
          const WDB = wordAt(8, 'Definitely Buy'), named = t > WDB;
          const hr3 = person(g, { x: w.x, y: GY, s: 1.15, pose: idle(pose, t, 3), facing: 1, color: named ? PAL.red : PAL.ink, seed: 3, expr: t > cue(12) + 1.3 ? 'happy' : 'neutral', wear: named ? 'specs' : null });
          // purchase: the product flies from the PURCHASE button into the hero's hand, then the bag
          const fly = prog(t, cue(12) + .6, cue(12) + 1.3);
          if (fly > 0 && fly < 1) { const fx = lerp(SX + SW - 190, hr3.handF[0], E.inOut(fly)), fy = lerp(SY + SH - 60, hr3.handF[1], E.inOut(fly)) - Math.sin(Math.PI * fly) * 160;
            fillPoly(g, rrectPoly(fx - 24, fy - 20, 48, 40, 6), PAL.ink); fillPoly(g, rrectPoly(fx - 5, fy - 20, 10, 40, 2), PAL.red); }
          const held = t >= cue(12) + 1.3 && t < cue(12) + 2.6;      // product in hand during the cheer, then it goes in the bag
          if (held) { const [px2, py2] = hr3.handF; fillPoly(g, rrectPoly(px2 - 24, py2 - 44, 48, 40, 6), PAL.ink); fillPoly(g, rrectPoly(px2 - 5, py2 - 44, 10, 40, 2), PAL.red); }
          shopBag(g, hr3.handF[0], hr3.handF[1], 1, prog(t, cue(12) + 2.6, cue(12) + 3.0));
          // "buy, not just cart": the product sits in a cart; the cart is crossed out
          const cp = prog(t, cue(10) + .1, cue(10) + .5) * (1 - prog(t, cue(11) - .4, cue(11)));
          cart(g, 300, 540, 1, cp);
          fadeAlpha(g, cp, () => crossMark(g, 300, 480, 80, prog(t, cue(10) + .7, cue(10) + 1.2), 16));
          browserWin(g, SX, SY, SW, SH, 'AMAZON', prog(t, cue(9) + .2, cue(9) + .8), (x, y, w2, h2) => {
            const pp = prog(t, cue(9) + 1.0, cue(9) + 1.5) * (1 - prog(t, cue(10) + 1.0, cue(10) + 1.5));
            if (pp > 0) popAt(g, x + w2 / 2, y + h2 / 2, E.back(pp), () => { const by = y + h2 / 2 + Math.sin(t * 3) * 8;
              fillPoly(g, rrectPoly(x + w2 / 2 - 90, by - 70, 180, 140, 18), PAL.ink); fillPoly(g, rrectPoly(x + w2 / 2 - 18, by - 70, 36, 140, 6), PAL.red); });
            fadeAlpha(g, 1 - .75 * prog(t, cue(12), cue(12) + .1), () => rows.forEach(([s, a], i) => checkRow(g, s, x + 40, y + 46 + i * 60, prog(t, a, a + .6), { size: 32 })));
            const bp = prog(t, cue(12) + .1, cue(12) + .6);
            if (bp > 0) popAt(g, x + w2 - 190, y + h2 - 62, E.back(bp), () => {
              fillPoly(g, rrectPoly(x + w2 - 330, y + h2 - 100, 280, 76, 38), PAL.red);
              g.font = font('head', 34); g.fillStyle = PAL.cream; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('PURCHASE', x + w2 - 190, y + h2 - 60);
            });
          });
        });
        miniBar(g, 1, prog(t, wordAt(8, 'Definitely Buy'), wordAt(8, 'Definitely Buy') + .6));
        fadeAlpha(g, 1 - prog(t, cue(9) - .3, cue(9)), () => headlineWords(g, t, ['20%', 'DEFINITELY', 'BUY'], [wordAt(8, '20 percentage'), wordAt(8, 'Definitely Buy'), wordAt(8, 'Definitely Buy') + .12], 140, 230, { size: 84, red: [1, 2] }));
        headline(g, 'LIKE AMAZON BUYERS', 140, 230, prog(t, cue(9) + .1, cue(9) + 1.1), { size: 72, red: [1], maxW: 760 });
        tag(g, 'NOT JUST CART', 300, 610, prog(t, cue(10) + .9, cue(10) + 1.3) * (1 - prog(t, cue(11) - .4, cue(11))), { size: 28 });
      } },

    /* 4. THEY COME TO US AS A LEAD  (cues 13-16)  the Amazon window becomes OUR WEBSITE -> LEAD ticket handed over -> features scroll waved off -> handshake */
    { id: 'lead', start: cue(13) - TR, end: cue(17) - .001, enter: { type: 'iris', x: 1340, y: 560, dur: TR },
      camera: t => { const a = t + cue(13) - TR; return tween([[cue(13) - TR, { x: 0, y: 0, z: 1.04 }], [cue(13) + 1.5, { x: 0, y: 0, z: 1 }], [cue(14) + 1.6, { x: -40, y: 10, z: 1.03 }],
        [cue(14) + 3.8, { x: 60, y: 30, z: 1.04 }], [cue(15) + .2, { x: 60, y: 30, z: 1.04 }], [cue(15) + 1.6, { x: 260, y: 30, z: 1.06 }],
        [cue(16) + 2.0, { x: 260, y: 30, z: 1.06 }], [cue(16) + 2.8, { x: 300, y: 60, z: 1.1 }]], a); },
      draw(g, t0, T, c) {
        const t = t0 + cue(13) - TR; NOW = t; dotGrid(g, c);
        const S = 1.1;
        world(g, c, () => {
          groundLine(g, GY, 1);
          // the same window morphs from AMAZON into OUR WEBSITE (same way of buying)
          const m = E.inOut(prog(t, cue(13) + .2, cue(13) + 1.2)), wa = (1 - .72 * prog(t, cue(14) + 1.8, cue(14) + 2.3)) * (1 - prog(t, cue(15) - .5, cue(15)));
          const [wx, wy, ww, wh] = mix([960, 300, 760, 520], [150, 380, 560, 400], m);
          if (wa > 0) fadeAlpha(g, wa, () => browserWin(g, wx, wy, ww, wh, m < .5 ? 'AMAZON' : 'OUR WEBSITE', 1, (x, y) => {
            if (m < 1) return;
            checkRow(g, 'ABOUT US', x + 40, y + 70, prog(t, cue(13) + 1.3, cue(13) + 1.8));
            checkRow(g, 'WHAT WE SELL', x + 40, y + 150, prog(t, cue(13) + 2.8, cue(13) + 3.3));
            checkRow(g, 'DECIDED', x + 40, y + 230, prog(t, cue(14) + .4, cue(14) + 1.0));
          }));
          // buyer (glasses, phone) walks from our website to SALES and hands over a LEAD ticket
          const w = walker([[cue(14) + 1.6, 860], [cue(14) + 3.8, 1300, E.out], [cue(15) + .1, 1300], [cue(15) + 1.0, 1170, E.out], [cue(16) + 1.0, 1170], [cue(16) + 2.2, 1300, E.out]], t, S, POSES.stand, 1);
          let pose = poseMix(w.pose, POSES.think, E.inOut(prog(t, cue(13) + .4, cue(13) + .9)) * (1 - prog(t, cue(14) + 1.0, cue(14) + 1.5)));
          const nod4 = [cue(13) + 1.3, cue(13) + 2.8, cue(14) + .4].reduce((s, a) => s + Math.sin(Math.PI * prog(t, a + .2, a + .6)) * 12, 0);
          pose = Object.assign({}, pose, { head: (pose.head || 0) + nod4 });
          pose = poseMix(pose, POSES.reach, E.inOut(prog(t, cue(14) + 3.4, cue(14) + 3.8)) * (1 - E.inOut(prog(t, cue(15), cue(15) + .4))));
          pose = poseMix(pose, POSES.stop, E.inOut(prog(t, cue(15) + 1.3, cue(15) + 1.7)) * (1 - E.inOut(prog(t, cue(15) + 3.0, cue(15) + 3.4))));
          pose = poseMix(pose, POSES.reach, E.inOut(prog(t, cue(16) + 2.2, cue(16) + 2.6)));
          const hr = sureBuyer(g, { x: w.x, y: GY, s: S, pose: idle(pose, t, 4), facing: t < cue(14) + 1.2 ? -1 : 1, color: PAL.red, seed: 4, wear: 'specs',
              expr: t > cue(14) + .9 ? (t > cue(15) + 1.3 && t < cue(15) + 3.0 ? 'neutral' : 'happy') : 'neutral' },
            prog(t, cue(14) + 1.0, cue(14) + 1.6) * (1 - prog(t, cue(14) + 3.0, cue(14) + 3.3)));
          // SALES (same scale as the buyer)
          let up = POSES.stand;
          up = poseMix(up, POSES.reach, E.inOut(prog(t, cue(14) + 3.9, cue(14) + 4.3)));                 // takes the ticket, then holds up the scroll
          up = poseMix(up, POSES.point, E.inOut(prog(t, cue(16), cue(16) + .4)));
          up = poseMix(up, POSES.reach, E.inOut(prog(t, cue(16) + 2.2, cue(16) + 2.6)));
          const ur = salesman(g, { x: 1560, y: GY, s: S, pose: idle(up, t, 5), facing: -1, seed: 5, expr: t > cue(14) + 4.4 ? 'happy' : 'neutral' });
          tag(g, 'SALES', 1560, GY + 70, prog(t, cue(13) + .3, cue(13) + .7), { size: 30 });
          briefcase(g, 1690, GY, 1, 1);
          // the LEAD ticket: appears in the buyer's hand, travels to the salesman's hand
          const lp = prog(t, cue(14) + 3.6, cue(14) + 3.9) * (1 - prog(t, cue(15) - .3, cue(15))), lm = E.inOut(prog(t, cue(14) + 4.0, cue(14) + 4.7));
          tag(g, 'LEAD', lerp(hr.handF[0], ur.handF[0], lm), lerp(hr.handF[1], ur.handF[1], lm) - 70 - Math.sin(Math.PI * lm) * 70, lp, { bg: PAL.red, size: 38 });
          // features scroll: unrolls from the salesman's hand, waved off, crossed, rolled back up
          const L = 300 * E.out(prog(t, cue(15) + .2, cue(15) + 1.2)) * (1 - E.inOut(prog(t, cue(15) + 2.8, cue(15) + 3.4)));
          featureScroll(g, ur.handF[0] - 95, ur.handF[1] + 10, L);
          crossMark(g, ur.handF[0] - 95, ur.handF[1] + 170, 70, prog(t, cue(15) + 1.8, cue(15) + 2.3) * (1 - prog(t, cue(15) + 2.8, cue(15) + 3.0)), 16);
          // what + how much, then a handshake
          speechBubble(g, 'WHAT WE HAVE', 1640, 320, ur.head[0] + 10, ur.head[1] - 30, prog(t, cue(16) + .2, cue(16) + .6) * (1 - prog(t, cue(16) + 2.0, cue(16) + 2.3)), { size: 34 });
          speechBubble(g, 'THIS IS THE PRICE', 1450, 405, ur.head[0] - 30, ur.head[1] - 30, prog(t, cue(16) + 1.2, cue(16) + 1.6) * (1 - prog(t, cue(16) + 2.0, cue(16) + 2.3)), { size: 34 });
          const shake = prog(t, cue(16) + 2.6, cue(16) + 2.8);
          if (shake > 0) { const mx = (hr.handF[0] + ur.handF[0]) / 2, my = (hr.handF[1] + ur.handF[1]) / 2 + Math.sin(t * 18) * 5 * (1 - prog(t, cue(16) + 3.6, cue(16) + 3.8));
            g.beginPath(); g.arc(mx, my, 14 * E.back(shake), 0, 7); g.fillStyle = PAL.ink; g.fill();
            badge(g, mx, my - 120, prog(t, cue(16) + 3.0, cue(16) + 3.5), 'tick', PAL.red, PAL.cream, 34); }
        });
        miniBar(g, 1, 1);
        const hA = (a, b) => { const q = prog(t, a - .1, b); return 1 - q * q; };   // exits: gentle ease-in over 0.4 s
        fadeAlpha(g, hA(cue(14) + 2.0, cue(14) + 2.3), () => {
          headline(g, 'SAME WITH US', 140, 230, prog(t, cue(13) + .1, cue(13) + 1.0), { size: 84, red: [2] });
        });
        fadeAlpha(g, hA(cue(15) - .3, cue(15)), () => headline(g, 'THEY COME AS A LEAD', 140, 230, prog(t, cue(14) + 2.3, cue(14) + 3.2), { size: 80, red: [4] }));
        fadeAlpha(g, hA(cue(16) - .3, cue(16)), () => headline(g, 'NO NEED TO SELL FEATURES', 140, 230, prog(t, cue(15) + .1, cue(15) + 1.0), { size: 72, red: [4], maxW: 1150 }));
        headline(g, "THEY'LL SURELY BUY", 140, 230, prog(t, cue(16) + .1, cue(16) + 1.0), { size: 80, red: [1] });
        tag(g, 'DEFINITELY BUY', 960, 990, prog(t, wordAt(16, 'Definitely Buy'), wordAt(16, 'Definitely Buy') + .5), { size: 34 });
      } },

    /* 5. CONFUSED BUYERS  (cues 17-20)  the bar returns; the 60% light up and pace; five questions with pictures */
    { id: 'confused', start: cue(17) - TRW, end: cue(21) - .001, enter: { type: 'wipe', dur: TRW },
      camera: t => { const a = t + cue(17) - TRW; return tween([[cue(17) - TRW, { x: 0, y: 0, z: 1.05 }], [cue(17) + 1.3, { x: 0, y: 0, z: 1 }], [cue(18), { x: 0, y: 0, z: 1 }],
        [cue(18) + 1.2, { x: 40, y: 30, z: 1.06 }], [cue(20), { x: 120, y: 30, z: 1.06 }], [cue(21), { x: 60, y: 20, z: 1.03 }]], a); },
      draw(g, t0, T, c) {
        const t = t0 + cue(17) - TRW; NOW = t; dotGrid(g, c);
        const W60 = wordAt(17, '60 percentage'), WCB = wordAt(17, 'Confused Buyers'), r6 = prog(t, W60, W60 + 1.0), rc = prog(t, WCB, WCB + .5);
        world(g, c, () => {
          groundLine(g, GY, 1);
          const labA = 1 - prog(t, cue(18) - .4, cue(18));
          spineBar(g, 1, [rgba(PAL.gray, .9), rgba(PAL.gray, .9), PAL.ink], 1, [labA, labA, 0]);
          if (r6 > 0) fadeAlpha(g, E.inOut(r6), () => spineBar(g, 1, [rgba(PAL.gray, .9), rgba(PAL.gray, .9), PAL.red], 1, [labA, labA, prog(t, WCB, WCB + .6) * labA]));   // 60% cross-fades to red
          const heads = [];
          const QT = [[cue(18) + .1, 4], [cue(18) + 2.6, 6], [cue(19) + .1, 8], [cue(20) + .1, 5], [cue(20) + 2.1, 9]];
          const focal = (QT.filter(([a]) => t >= a).pop() || [0, -1])[1];
          for (let i = 0; i < 10; i++) {
            const conf = i >= 4, on = conf ? E.inOut(prog(t, WCB + (i - 4) * .08, WCB + .6 + (i - 4) * .08)) : 0;
            const amp = focal < 0 ? 1 : (i === focal ? 1 : .35);            // ambient for the rest, full motion for the speaker
            const pc = pacing(SLOT(i), t, i, on * amp);
            const F = { x: conf ? pc.x : SLOT(i), y: GY, s: .75, pose: idle(conf ? pc.pose : (i < 2 ? POSES.cross : POSES.stand), t, i), facing: conf ? pc.facing : 1, seed: i,
              color: conf ? (on > .5 ? PAL.red : PAL.ink) : rgba(PAL.gray, .9), expr: conf && on > .5 ? 'confused' : 'neutral', wear: !conf || on > .5 ? WEAR[i] : null };
            const r = conf ? person(g, F) : (i < 2 ? neverBuyer(g, F) : sureBuyer(g, F, 1));
            heads.push(r.head);
          }
          const Q = [['Do I need it?', 760, 470, 4, cue(18) + .1, 'need'], ['Buy it from whom?', 1180, 360, 6, cue(18) + 2.6, 'whom'],
                     ['Will I use it?', 1590, 470, 8, cue(19) + .1, 'use'], ['Now or later?', 1000, 560, 5, cue(20) + .1, 'when'], ['Or something else?', 1460, 580, 9, cue(20) + 2.1, 'else']];
          const col = E.in(prog(t, cue(21) - .9, cue(21) - .3));     // questions get sucked into one knot
          Q.forEach(([s, x, y, i, a, ic], k) => {
            const next = Q[k + 1] ? Q[k + 1][4] : 1e9, dim = 1 - .72 * prog(t, next + 1.2, next + 1.6) * (1 - col);
            const qx = lerp(x, 1180, col), qy = lerp(y, 460, col);
            qBubble(g, s, qx, qy, heads[i][0], heads[i][1] - 30, prog(t, a, a + .45) * (1 - col), ic, dim);
          });
        });
        headlineWords(g, t, ['60%', 'CONFUSED', 'BUYERS'], [W60, WCB, WCB + .12], 140, 230, { size: 84, red: [1, 2] });
      } },

    /* 6. WHY SALES EXISTS  (cues 21-24)  one tangled thread -> SALES takes the loose end and pulls -> loops come undone from his end
       -> straight thread -> released, it levels out, sinks behind the group and lands under their feet as the 60% bar */
    { id: 'clarity', start: cue(21) - TR, end: Math.max(cue(25), CONFIG.duration), enter: { type: 'iris', x: 1180, y: 460, dur: TR },
      camera: t => { const a = t + cue(21) - TR; return tween([[cue(21) - TR, { x: 0, y: 0, z: 1.08 }], [cue(21) + 1.5, { x: 0, y: 0, z: 1 }], [cue(23), { x: 0, y: 0, z: 1 }],
        [cue(23) + 1.6, { x: 50, y: 30, z: 1.05 }], [cue(24) + .6, { x: 50, y: 30, z: 1.05 }], [cue(24) + 1.8, { x: 0, y: 0, z: 1 }]], a); },
      draw(g, t0, T, c) {
        const t = t0 + cue(21) - TR; NOW = t; dotGrid(g, c);
        const S = .85, N = THREAD.length, R0 = 600, R1 = 1260, LY = 430;
        // timeline (all on the SRT clock)
        const P0 = cue(23) + .3, P1 = cue(23) + 2.9;                       // the pull
        const un = tween([[P0, 0], [P0 + .9, .38, E.inOut], [P0 + 1.15, .34, E.inOut], [P0 + 1.9, .74, E.inOut], [P0 + 2.1, .71, E.inOut], [P1, 1, E.inOut]], t);
        const lv = E.inOut(prog(t, cue(24) + .9, cue(24) + 1.5));          // released: levels out to the bar's length
        const dv = E.inOut(prog(t, cue(24) + 1.5, cue(24) + 2.2));         // sinks behind the group to the ground
        const land = cue(24) + 2.2, grow = E.out(prog(t, land, land + .5));
        const clear = t > cue(24) + .2;
        // SALES walks in, takes the loose end, leans back while pulling, lets go
        const w = walker([[cue(22) + .2, 2100], [cue(22) + 2.0, 1560, E.out], [P0, 1560], [P1, 1630, E.inOut]], t, S, POSES.reach, -1);
        let up = poseMix(w.pose, POSES.reach, E.inOut(prog(t, cue(22) + 1.8, cue(22) + 2.3)));
        up = Object.assign({}, up, { lean: (up.lean || 0) + 6 * Math.sin(Math.PI * prog(t, P0 - .3, P0)) - 10 * Math.sin(Math.PI * clamp((t - P0) / (P1 - P0))) });   // lean in, then pull back
        up = poseMix(up, POSES.stand, E.inOut(prog(t, cue(24) + .9, cue(24) + 1.4)));
        up = poseMix(up, POSES.point, E.inOut(prog(t, land + .3, land + .8)));
        world(g, c, () => {
          groundLine(g, GY, 1);
          // the bar (drawn first: everything else stands on it)
          if (grow > 0) spineBar(g, 1, [rgba(PAL.gray, .9), rgba(PAL.gray, .9), PAL.red], [grow, grow, 1], [0, 0, grow], { x: 160, w: 1100, grow, labSize: 28 });
          // hand position (from the salesman's pose) for the thread end
          let hand = null;
          const drawSales = () => { if (t > cue(22)) hand = salesman(g, { x: w.x, y: GY, s: S, pose: idle(up, t, 7), facing: -1, seed: 7, expr: 'happy' }).handF; };
          // ---- the thread ----
          const breathe = 1 + .025 * Math.sin(t * 2.2) * (1 - un);
          const K = i => { const [x, y] = THREAD[i]; return [THC[0] + (x - THC[0]) * breathe, THC[1] + (y - THC[1]) * breathe]; };
          const threadPts = (h) => {
            // knot from the far end up to the unravel front, then straight to the hand
            const f = (N - 1) * (1 - un), fi = Math.floor(f), fr = f - fi, out = [];
            for (let i = 0; i <= fi; i++) out.push(K(i));
            if (fi < N - 1) { const a = K(fi), b = K(fi + 1); out.push([lerp(a[0], b[0], fr), lerp(a[1], b[1], fr)]); }
            out.push(h); return out;
          };
          const sinking = dv > 0 || lv > 0;
          if (sinking) {
            // released: straight thread -> level band of the bar's width -> sinks and thickens (behind the people)
            drawSales();
            const A0 = K(0), B0 = hand;
            const a = [lerp(A0[0], R0 + 8, lv), lerp(A0[1], LY, lv)], b = [lerp(B0[0], R1 - 8, lv), lerp(B0[1], LY, lv)];
            const y = lerp(a[1], GY + BAR.h / 2, dv), th = lerp(8, BAR.h, dv);
            if (grow < 1) {
              const ya = lerp(a[1], GY + BAR.h / 2, dv), yb = lerp(b[1], GY + BAR.h / 2, dv);
              const poly = dv > 0 ? rrectPoly(a[0], y - th / 2, b[0] - a[0], th, Math.min(14, th / 2)) : null;
              if (poly) { fadeAlpha(g, 1 - dv, () => fillPoly(g, poly, PAL.ink)); fadeAlpha(g, dv, () => fillPoly(g, poly, PAL.red)); }
              else strokeOn(g, [[a[0], ya], [b[0], yb]], 1, PAL.ink, 8);
            }
          }
          // the six (drawn after the band so it passes behind them); they hop when the bar lands
          const heads = [];
          for (let i = 0; i < 6; i++) {
            const calm = E.inOut(prog(t, cue(24) + .1 + i * .08, cue(24) + .7 + i * .08)), pc = pacing(658 + i * 108, t, i, (1 - calm) * .45);
            const hop = 34 * Math.sin(Math.PI * prog(t, land + i * .05, land + .45 + i * .05));
            const pose = poseMix(poseMix(pc.pose, i % 2 ? POSES.cheer : POSES.stand, calm), POSES.cheer, E.inOut(prog(t, land + .3, land + .8)));   // all arms up once they stand on the bar
            const r = person(g, { x: pc.x, y: GY - hop, s: S, pose: idle(pose, t, i), facing: calm > .5 ? 1 : pc.facing, seed: 10 + i, color: PAL.red, expr: clear ? 'happy' : 'confused', wear: WEAR[4 + i] });
            heads.push(r.head);
          }
          if (!sinking) {
            drawSales();
            const dp = prog(t, cue(21) + .1, cue(21) + 1.8);                       // the tangle draws on
            const grab = prog(t, cue(22) + 2.0, cue(22) + 2.6);                    // he takes the loose end
            if (un <= 0) {
              const knot = []; for (let i = 0; i < N; i++) knot.push(K(i));
              if (dp > 0) strokeOn(g, knot, dp, PAL.ink, 7);
              if (grab > 0 && hand) strokeOn(g, [K(N - 1), hand], grab, PAL.ink, 7);
            } else if (hand) strokeOn(g, threadPts(hand), 1, PAL.ink, 7);
          }
          tag(g, 'SALES', w.x, GY + 70, prog(t, cue(22) + 1.8, cue(22) + 2.2), { size: 30 });
          tag(g, 'CLARITY', 930, 350, prog(t, cue(24) + .1, cue(24) + .5) * (1 - prog(t, cue(24) + 1.3, cue(24) + 1.6)), { size: 44, bg: PAL.red });
          heads.forEach((h, i) => badge(g, h[0], h[1] - 100, prog(t, land + .4 + i * .08, land + .9 + i * .08), 'tick', PAL.red, PAL.cream, 22));
        });
        const hA = (a, b) => { const q = prog(t, a - .1, b); return 1 - q * q; };   // exits: gentle ease-in over 0.4 s
        fadeAlpha(g, hA(cue(22) - .3, cue(22)), () => {
          headline(g, 'SO MANY CONFUSIONS', 140, 230, prog(t, cue(21) + .1, cue(21) + 1.0), { size: 84, red: [2] });
          subline(g, 'They need help to decide', 140, 302, prog(t, cue(21) + 2.0, cue(21) + 2.5), 0, { size: 40 });
        });
        fadeAlpha(g, hA(cue(23) - .3, cue(23)), () => {
          headline(g, 'ONLY WITH HELP', 140, 230, prog(t, cue(22) + .1, cue(22) + 1.0), { size: 84, red: [2] });
          subline(g, 'can they decide what they need', 140, 302, prog(t, cue(22) + 1.4, cue(22) + 1.9), 0, { size: 40 });
        });
        headline(g, 'THIS IS WHY SALES EXISTS', 140, 230, prog(t, cue(23) + .1, cue(23) + 1.1), { size: 80, red: [3] });
        subline(g, 'Clarity. Help to decide.', 140, 302, prog(t, cue(24) + .6, cue(24) + 1.1), 0, { size: 40 });
      } },
  ];

  STORYBOARD = [
    { t: 1.6, title: 'Cue 1: buyers walk in' },
    { t: cue(3) - .3, title: 'Cue 2: the bar splits 20 | 20 | 60' },
    { t: cue(4) - 1.0, title: 'Cue 3: first 20% = Never Buy' },
    { t: cue(5) - .4, title: 'Cue 4: why are they here?' },
    { t: cue(7) - .5, title: 'Cues 5-6: no need, empty wallet, pitches bounce off' },
    { t: cue(8) - 1.3, title: 'Cue 7: sales not needed' },
    { t: cue(9) - .3, title: 'Cue 8: 20% Definitely Buy' },
    { t: cue(12) - .3, title: 'Cues 9-11: like an Amazon buyer' },
    { t: cue(13) - 1.0, title: 'Cue 12: purchase, done' },
    { t: cue(14) + 1.0, title: 'Cue 13: our website, about us' },
    { t: cue(15) - .6, title: 'Cue 14: they come as a lead' },
    { t: cue(16) - .4, title: 'Cue 15: no need to sell features' },
    { t: cue(17) - 1.3, title: 'Cue 16: what we have + the price → buy' },
    { t: cue(18) - .4, title: 'Cue 17: 60% confused buyers' },
    { t: cue(21) - 1.1, title: 'Cues 18-20: their five questions' },
    { t: cue(22) - .4, title: 'Cue 21: so many confusions' },
    { t: cue(23) - .4, title: 'Cue 22: help arrives' },
    { t: cue(25) - .3, title: 'Cues 23-24: why sales exists' },
  ];
  MUSIC.accents = [cue(2), cue(3), cue(8), cue(12), cue(17), cue(23), cue(24)];
  SFX_CUES = [
    { t: cue(2), type: 'draw' }, { t: cue(2) + .7, type: 'thud' }, { t: cue(3), type: 'pop' },
    ...[cue(4), cue(13), cue(21)].map(x => ({ t: x - TR, type: 'whoosh' })), ...[cue(8), cue(17)].map(x => ({ t: x - TRW, type: 'whoosh' })),
    { t: cue(4) + 1.4, type: 'pop' }, { t: cue(4) + 1.7, type: 'pop' }, { t: cue(5) + 1.3, type: 'pop' },
    ...[0, 1, 2].flatMap(k => [{ t: cue(6) + 1.4 + k, type: 'pop' }, { t: cue(6) + 1.9 + k, type: 'thud' }]),
    { t: cue(7) + .5, type: 'thud' },
    { t: cue(9) + .2, type: 'pop' }, { t: cue(10) + .1, type: 'pop' }, { t: cue(10) + .7, type: 'draw' },
    ...[cue(10) + 1.6, cue(10) + 3.0, cue(11) + .1, cue(11) + 1.1, cue(11) + 2.4, cue(11) + 3.6].map(x => ({ t: x + .35, type: 'click' })),
    { t: cue(12) + .1, type: 'pop' }, { t: cue(12) + .6, type: 'whoosh' }, { t: cue(12) + 1.3, type: 'chime' }, { t: cue(12) + 2.6, type: 'pop' },
    { t: cue(13) + .2, type: 'whoosh' }, ...[cue(13) + 1.3, cue(13) + 2.8, cue(14) + .4].map(x => ({ t: x + .35, type: 'click' })),
    { t: cue(14) + 3.6, type: 'pop' }, { t: cue(14) + 4.0, type: 'whoosh' },
    { t: cue(15) + .2, type: 'draw' }, { t: cue(15) + 1.8, type: 'draw' },
    { t: cue(16) + .2, type: 'pop' }, { t: cue(16) + 1.2, type: 'pop' }, { t: cue(16) + 2.6, type: 'click' }, { t: cue(16) + 3.0, type: 'chime' },
    ...[cue(18) + .1, cue(18) + 2.6, cue(19) + .1, cue(20) + .1, cue(20) + 2.1].map(x => ({ t: x, type: 'pop' })),
    { t: cue(21) - .9, type: 'whoosh' }, { t: cue(21) + .1, type: 'draw' }, { t: cue(22) + 2.0, type: 'click' },
    { t: cue(23) + 1.2, type: 'draw' }, { t: cue(23) + 2.2, type: 'draw' }, { t: cue(24) + .1, type: 'chime' },
    { t: cue(24) + 1.5, type: 'whoosh' }, { t: cue(24) + 2.2, type: 'thud' }, { t: cue(24) + 2.6, type: 'pop' },
  ];
  CUES = SRT_TEXT.map((text, i) => ({ start: C[i], end: C[i + 1], text }));
}
